import{_ as e}from"./chunks/00-sidebar-overview.Cutxsm52.js";import{_ as o,o as r,c as a,a0 as s}from"./chunks/framework.DfN8ZSCw.js";const p=JSON.parse('{"title":"What is filebox","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"en/guide/introduction.md","lastUpdated":null}'),n={name:"en/guide/introduction.md"};function i(l,t,d,c,h,u){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="what-is-filebox" tabindex="-1">What is filebox <a class="header-anchor" href="#what-is-filebox" aria-label="Permalink to &quot;What is filebox&quot;">​</a></h1><p>filebox is a <strong>read-only remote file browser</strong> for labs / HPC / self-hosted servers: install a small Agent on each machine, run a Hub on a host you control, open one HTTPS page in a browser, and you can browse files, preview plots and datasets, search workspaces, and check system load.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser ──HTTPS──▶ Hub ◀──WSS (outbound)── Agent ──▶ local files</span></span></code></pre></div><p><img src="'+e+'" alt="filebox UI overview (live Hub + Agent)"></p><ul><li><strong>Browser</strong>: talks only to the Hub, never directly to Agents.</li><li><strong>Hub</strong>: authenticates users, serves the frontend, routes requests to the right machine.</li><li><strong>Agent</strong>: runs on the target host and <strong>dials out</strong> to the Hub. The target needs no public IP, inbound ports, VPN, or port forwarding. After disconnects it reconnects automatically with a stable identity — no duplicate sidebar entries.</li></ul><h2 id="who-it-is-for" tabindex="-1">Who it is for <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who it is for&quot;">​</a></h2><p>Researchers, analysts, and data scientists whose results live as files on shared servers and who need to <strong>glance at figures, tables, and logs</strong> from a phone or laptop without <code>scp</code>-ing an entire archive for a quick look.</p><p>filebox is not a sync/drive product and not a full remote desktop — it is the “front door” to result files: open, preview, search, occasionally upload a small scratch file, or open a TOTP-protected terminal.</p><h2 id="what-you-can-do-v2-1-0" tabindex="-1">What you can do (v2.1.0) <a class="header-anchor" href="#what-you-can-do-v2-1-0" aria-label="Permalink to &quot;What you can do (v2.1.0)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Notes</th><th>Docs</th></tr></thead><tbody><tr><td><strong>Files</strong></td><td>Smooth large listings, breadcrumbs, filters, pins, multi-tab preview</td><td><a href="/filebox/docs/en/features/browse">Browse files</a></td></tr><tr><td><strong>Explorer</strong></td><td>Tree-style browsing; shares current location with Files</td><td><a href="/filebox/docs/en/features/explorer">Explorer</a></td></tr><tr><td><strong>Search</strong></td><td>Filename or content regex; floating panel / bottom sheet</td><td><a href="/filebox/docs/en/features/search">Search</a></td></tr><tr><td><strong>Collections</strong></td><td>Virtual file groups across directories — no copy, no move</td><td><a href="/filebox/docs/en/features/collections">Collections</a></td></tr><tr><td><strong>Transfer</strong></td><td>The only writable scratch upload folder (quota, no overwrite)</td><td><a href="/filebox/docs/en/features/transfer">Transfer</a></td></tr><tr><td><strong>Terminal</strong></td><td>Optional; Agent-local TOTP-gated interactive shell (<strong>not sandboxed</strong>)</td><td><a href="/filebox/docs/en/features/terminal">Terminal</a></td></tr><tr><td><strong>Settings</strong></td><td>Manage roots, Office preview toggle</td><td><a href="/filebox/docs/en/guide/first-login">First login</a></td></tr><tr><td><strong>System</strong></td><td>CPU / memory / load / per-user usage / process table</td><td><a href="/filebox/docs/en/features/stats">System monitor</a></td></tr><tr><td><strong>Audit</strong></td><td>Login audit (Hub-level; does not require a selected Agent)</td><td><a href="/filebox/docs/en/ops/hub">Hub ops</a></td></tr></tbody></table><h2 id="default-security-boundaries" tabindex="-1">Default security boundaries <a class="header-anchor" href="#default-security-boundaries" aria-label="Permalink to &quot;Default security boundaries&quot;">​</a></h2><ul><li>Browse protocol is <strong>read-only</strong>: no remote edit, delete, or rename.</li><li>Sensitive paths (<code>.ssh/</code>, <code>.env*</code>, <code>*.pem</code>, …) are denied by default even inside allowed roots.</li><li>Browse is strictly confined to added roots; <code>..</code> and symlink escapes are blocked.</li><li>Two explicit exceptions (capability / local config required): <ul><li><strong>Transfer</strong>: writes only into the Agent’s dedicated scratch directory.</li><li><strong>Terminal</strong>: Agent-local TOTP-gated interactive shell (<strong>not sandboxed</strong> — anything the OS user can do).</li></ul></li></ul><p>See <a href="/filebox/docs/en/features/security">Security &amp; sensitive files</a>.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p>A newcomer can install and use end-to-end from these docs: start with <a href="./quick-start">Quick start</a>, then <a href="./install-hub">Install Hub</a> → <a href="./install-agent">Install Agent</a> → <a href="./first-login">First login &amp; add roots</a>.</p>',15)])])}const b=o(n,[["render",i]]);export{p as __pageData,b as default};
